-- EvolvixOS Registry Seed Data
-- Generated from registry.db
-- 323 GitHub-discovered skills

CREATE TABLE IF NOT EXISTS model_registry (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    category TEXT,
    description TEXT,
    source TEXT,
    engine TEXT DEFAULT 'github-discovered',
    status TEXT DEFAULT 'discovered',
    stars INTEGER DEFAULT 0,
    language TEXT,
    topics TEXT,
    url TEXT,
    quality_score REAL DEFAULT 0,
    created_date TEXT
);

